std::vector<std::vector<int>> rows(3, std::vector<int>(n));
int best = 0;
for (int r = 0; r < n; ++r) {
    auto& row = rows[r % 3];
    for (int& x : row) {
        std::cin >> x;
        x = (x == 1);
    }
    if (r < 2) continue;
    int sum = 0;
    for (int c = 0; c < n; ++c) {
        for (auto& v : rows) sum += v[c];
        if (c >= 3)
            for (auto& v : rows) sum -= v[c - 3];
        if (c >= 2) best = std::max(best, sum);
    }
}
